package com.yeyamo_mobile.api.moderation_trust_service.infrastructure.messaging;import java.time.Instant;import java.util.UUID;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;import com.fasterxml.jackson.databind.*;import com.yeyamo_mobile.api.moderation_trust_service.application.ModerationService;
@Component public class SourceEventConsumer{private final ObjectMapper mapper;private final ModerationService service;private final ProcessedEventRepository processed;public SourceEventConsumer(ObjectMapper m,ModerationService s,ProcessedEventRepository p){mapper=m;service=s;processed=p;}
 @KafkaListener(topics="${yeyamo.kafka.topics.content-events:content.events}",groupId="${spring.kafka.consumer.group-id:moderation-trust-service}")@Transactional public void content(String raw)throws Exception{consume(raw,"content-service");}
 @KafkaListener(topics="${yeyamo.kafka.topics.interaction-events:interaction.events}",groupId="${spring.kafka.consumer.group-id:moderation-trust-service}")@Transactional public void interaction(String raw)throws Exception{consume(raw,"interaction-service");}
 @KafkaListener(topics="${yeyamo.kafka.topics.admin-events:admin.events}",groupId="${spring.kafka.consumer.group-id:moderation-trust-service}")@Transactional public void admin(String raw)throws Exception{consume(raw,"admin-service");}
 public void consume(String raw,String expectedProducer)throws Exception{JsonNode e=mapper.readTree(raw);UUID id=UUID.fromString(required(e,"eventId"));if(processed.existsById(id))return;int version=e.path("eventVersion").asInt(0);if(version!=1)throw new IllegalArgumentException("Unsupported event version");String producer=required(e,"producer");if(!expectedProducer.equals(producer))throw new IllegalArgumentException("Unexpected event producer");String type=required(e,"eventType");service.recordExternal(id.toString(),type,text(e,"aggregateId","unknown"),text(e,"actorId","system"),text(e,"correlationId",id.toString()),producer);var done=new ProcessedEventEntity();done.setEventId(id);done.setEventType(type);done.setProcessedAt(Instant.now());processed.save(done);}
 private String required(JsonNode n,String f){String v=text(n,f,null);if(v==null||v.isBlank())throw new IllegalArgumentException(f+" is required");return v;}private String text(JsonNode n,String f,String d){JsonNode v=n.get(f);return v==null||v.isNull()?d:v.asText();}}
